/**
 * Headers for every page the Worker answers (the app's index.html at its routes and at /, and the landing page).
 * public/_headers can't do it: Cloudflare applies that file to the assets' own responses only, "not to responses
 * generated by your Worker code", and these pages come from here. /api has its own (Hono's secureHeaders, app.ts).
 *
 * No page is ever framed (a hidden frame over a button would be clickjacking; the consent screen at /authorize most
 * of all), and the policy names nothing the app loads, so it can't break a screen: scripts and styles are left to
 * the app (docs/security.md says why there is no script policy yet).
 */
export const PAGE_HEADERS: Readonly<Record<string, string>> = {
  "Content-Security-Policy": "frame-ancestors 'none'; base-uri 'self'; object-src 'none'",
  "X-Frame-Options": "DENY",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Strict-Transport-Security": "max-age=15552000; includeSubDomains",
};

export function setPageHeaders(headers: Headers) {
  for (const [name, value] of Object.entries(PAGE_HEADERS)) headers.set(name, value);
}
